    private static void ResumeTrampoline(nint sink)
    {
        try
        {
            if (Gst.GObject.Object.TryGetOrFabricate(sink) is not AudioSink managed)
            {
                ChainUpResume(sink);
                return;
            }

            managed.OnResume();
        }
        catch (Exception exception)
        {
            Gst.Interop.ExceptionTrap.Report(exception);
        }
    }
}
